  ('la-pt', 'la-t072', 'frase', 'B1', array['trecho']::text[], null, 'cdd0c930', array['Nem a todos agrada o arvoredo e a humilde tamargueira;', 'Nem a todos agradam os arvoredos e as humildes tamargueiras;', 'Nem a todos agradavam os arvoredos e as humildes tamargueiras;', 'Nem todos agradam aos arvoredos e às humildes tamargueiras;', 'Nem todos os arvoredos agradam, e as humildes tamargueiras;']::text[]),
